# Hypothesis for particle system
# PLEKT rule: Each PLEKT moves toward the nearest WOVVE (by wovve_dist = |wrap_dx|^2 + |wrap_dy|)
# by step = (sign(wrap_dx), sign(wrap_dy)) where wrap = (target - current) % 8
# sign: +1 for wrap in [1,4], -1 for wrap in [5,7], 0 for wrap = 0
# WOVVE rule: Each WOVVE moves toward the nearest PLEKT by wovve_dist with same step rule
# If WOVVEs don't move (stay still), they remain in place

def step(dir):
    if 1 <= dir <= 4:
        return 1
    elif 5 <= dir <= 7:
        return -1
    else:
        return 0

def wrap_diff(target, current):
    return (target - current) % 8

def wovve_dist(p, q):
    dx = wrap_diff(q['x'], p['x'])
    dy = wrap_diff(q['y'], p['y'])
    # Use shortest wrap for |wrap_dx|
    if dx > 4:
        dx = 8 - dx
    return dx * dx + dy

def chebyshev(p, q):
    dx = abs(wrap_diff(q['x'], p['x']))
    dy = abs(wrap_diff(q['y'], p['y']))
    if dx > 4:
        dx = 8 - dx
    if dy > 4:
        dy = 8 - dy
    return max(dx, dy)

def nearest(list_a, list_b, dist_fn):
    best_a = None
    best_dist = float('inf')
    for a in list_a:
        for b in list_b:
            d = dist_fn(a, b)
            if d < best_dist:
                best_dist = d
                best_a = a
    return best_a

def hidden_rule_fn(state):
    plekts = [p for p in state if p['type'] == 'PLEKT']
    wovves = [p for p in state if p['type'] == 'WOVVE']

    next_state = []

    # PLEKTs move toward nearest WOVVE
    for p in plekts:
        target = nearest([p], wovves, wovve_dist)
        if target:
            dx = wrap_diff(target['x'], p['x'])
            dy = wrap_diff(target['y'], p['y'])
            sx = step(dx)
            sy = step(dy)
            next_state.append({'type': 'PLEKT', 'x': (p['x'] + sx) % 8, 'y': (p['y'] + sy) % 8})
        else:
            next_state.append({'type': 'PLEKT', 'x': p['x'], 'y': p['y']})

    # WOVVEs move toward nearest PLEKT
    for p in wovves:
        target = nearest([p], plekts, wovve_dist)
        if target:
            dx = wrap_diff(target['x'], p['x'])
            dy = wrap_diff(target['y'], p['y'])
            sx = step(dx)
            sy = step(dy)
            next_state.append({'type': 'WOVVE', 'x': (p['x'] + sx) % 8, 'y': (p['y'] + sy) % 8})
        else:
            next_state.append({'type': 'WOVVE', 'x': p['x'], 'y': p['y']})

    return next_state
